local function append_unique(target, values)
  local seen = {}
  for _, value in ipairs(target) do seen[value] = true end
  for _, value in ipairs(values) do
    if not seen[value] then table.insert(target, value); seen[value] = true end
  end
end

function M.apply(records)
  for _, record in ipairs(records) do
    local item = data[record.text]
    if item then
      append_unique(record.qp, item.qp)
      append_unique(record.fly, item.fly)
    end
  end
end

return M
